/* デザイントークン (SSOT は brand.json)。Height tone = warm cream + terracotta + serif heading。
   常時ライトのトーンのため prefers-color-scheme: dark ブロックは設けない。 */
:root {
  --brand-primary-50: #fbeee9;
  --brand-primary-500: #d06846;
  --brand-primary-600: #c85a3c;
  --brand-primary-700: #a8462d;

  --brand-neutral-0: #ffffff;
  --brand-neutral-50: #f7f3ec;
  --brand-neutral-100: #efe9df;
  --brand-neutral-200: #e4dccf;
  --brand-neutral-300: #d6ccbb;
  --brand-neutral-400: #b3a894;
  --brand-neutral-500: #8c8271;
  --brand-neutral-600: #6b6252;
  --brand-neutral-700: #4e4739;
  --brand-neutral-800: #332e25;
  --brand-neutral-900: #211d17;

  --brand-success: #4b7f52;
  --brand-warning: #d08c2a;
