      setError(body?.error?.message ?? "保存に失敗しました");
      return;
    }
    if (!label) setName("");
    onDone?.();
    startTransition(() => router.refresh());
  }

  return (
    <form onSubmit={submit} className="flex flex-col gap-2">
      <Input
        type="text"
        aria-label="ラベル名"
