          {boardLabels.length === 0 ? (
            <span className="text-xs text-slate-400">ボードにラベルがありません</span>
          ) : (
            boardLabels.map((l) => {
              const cls =
                LABEL_COLOR_CLASS[l.color as LabelColor] ?? "bg-slate-200 text-slate-800";
              return (
                <button
                  key={l.id}
                  type="button"
                  onClick={() => toggle(l)}
                  aria-pressed={assignedIds.has(l.id)}
                  className="flex items-center justify-between gap-2 rounded px-2 py-1 text-left text-xs hover:bg-slate-50"
                >
                  <span className={`rounded px-2 py-0.5 ${cls}`}>{l.name}</span>
                  <span className="text-slate-500">
                    {assignedIds.has(l.id) ? "付与済み ✓" : "付与"}
                  </span>
                </button>
              );
            })
          )}
        </div>
      )}
    </div>
  );
}

