"use client";

// spec/004_card_movement_archive_restore.md § 画面（ドラッグ&ドロップ）
// HTML5 Drag and Drop API（依存追加なし）。ドロップ確定で move / list move API を呼ぶ。
import { useState } from "react";
import { useRouter } from "next/navigation";
import CardItem from "./CardItem";
import CardCreateForm from "./CardCreateForm";
import ListHeader from "./ListHeader";

type Label = { id: string; name: string; color: string };
type Card = {
  id: string;
  listId: string;
  title: string;
  description: string;
  order: number;
  dueDate?: string | Date | null;
  labels?: Label[];
};
type List = { id: string; boardId: string; title: string; order: number };
export type Column = { list: List; cards: Card[] };

type Drag =
  | { type: "card"; cardId: string; sourceListId: string }
  | { type: "list"; listId: string }
  | null;

export default function Board({
  columns,
  boardLabels = [],
  filteredCardIds = null,
}: {
  columns: Column[];
  boardLabels?: Label[];
  filteredCardIds?: string[] | null;
}) {
  const router = useRouter();
  const [drag, setDrag] = useState<Drag>(null);
  const visible = filteredCardIds === null ? null : new Set(filteredCardIds);

  async function moveCard(targetListId: string, targetOrder: number) {
    if (!drag || drag.type !== "card") return;
    await fetch(`/api/cards/${drag.cardId}/move`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sourceListId: drag.sourceListId,
        targetListId,
        targetOrder,
      }),
    });
    setDrag(null);
    router.refresh();
  }

  async function moveList(targetOrder: number) {
    if (!drag || drag.type !== "list") return;
    await fetch(`/api/lists/${drag.listId}/move`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ targetOrder }),
    });
    setDrag(null);
    router.refresh();
  }

  function dropOnColumn(col: Column, colIndex: number) {
    if (drag?.type === "list") {
      moveList(colIndex);
    } else if (drag?.type === "card") {
      // 空きエリアへのドロップ = 末尾へ。同一リストは対象を除いた末尾 index。
      const append =
        drag.sourceListId === col.list.id ? col.cards.length - 1 : col.cards.length;
      moveCard(col.list.id, Math.max(0, append));
    }
  }

  return (
    <div className="mt-6 flex flex-nowrap gap-4 overflow-x-auto pb-4">
      {columns.map((col, colIndex) => (
        <section
          key={col.list.id}
          className="w-72 shrink-0 rounded-lg bg-secondary p-3"
          draggable
          onDragStart={(e) => {
            e.stopPropagation();
            setDrag({ type: "list", listId: col.list.id });
          }}
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            e.preventDefault();
            dropOnColumn(col, colIndex);
          }}
        >
          <ListHeader list={col.list} />
          <ul className="flex min-h-[12px] flex-col gap-2">
            {col.cards
              .filter((card) => visible === null || visible.has(card.id))
              .map((card, cardIndex) => (
                <li
                  key={card.id}
                  draggable
                  onDragStart={(e) => {
                    e.stopPropagation();
                    setDrag({ type: "card", cardId: card.id, sourceListId: col.list.id });
                  }}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    if (drag?.type === "card") moveCard(col.list.id, cardIndex);
                  }}
                >
                  <CardItem card={card} boardLabels={boardLabels} />
                </li>
              ))}
          </ul>
          <div className="mt-3">
            <CardCreateForm listId={col.list.id} />
          </div>
        </section>
      ))}
    </div>
  );
}

// design/005_008_ui_features_ui.md § Atom: LabelChip
import { LABEL_COLOR_CLASS, type LabelColor } from "@/lib/labelColors";

type Label = { id: string; name: string; color: string };

export default function LabelChip({
  label,
  onRemove,
}: {
  label: Label;
  onRemove?: () => void;
}) {
  const cls = LABEL_COLOR_CLASS[label.color as LabelColor] ?? "bg-slate-200 text-slate-800";
  return (
    <span
      className={`inline-flex items-center gap-1 rounded px-2 py-0.5 text-xs font-medium ${cls}`}
    >
      {label.name}
      {onRemove && (
        <button
          type="button"
          onClick={onRemove}
          aria-label={`ラベル ${label.name} を解除`}
          className="ml-0.5 text-current/70 hover:text-current"
        >
          ×
        </button>
      )}
    </span>
  );
}

// spec/001_boards.md § 画面（ボード一覧）
import Link from "next/link";
import { boardRepository } from "@/lib/repository/board";
import AppShell from "@/components/layout/AppShell";
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { CURRENT_USER, boardStats, initials } from "@/lib/mockMeta";
import BoardCreateForm from "./_components/BoardCreateForm";

export const dynamic = "force-dynamic";

export default async function Home() {
  const boards = await boardRepository.list();

  return (
    <AppShell
      user={CURRENT_USER}
      boards={boards.map((b) => ({ id: b.id, title: b.title }))}
      breadcrumb={[{ label: "ボード一覧" }]}
    >
      <div className="w-full max-w-6xl mx-auto px-6 py-8">
        <header className="mb-6 flex items-center justify-between">
          <h1 className="font-heading text-2xl font-semibold">ボード一覧</h1>
          <BoardCreateForm />
        </header>

        {boards.length === 0 ? (
          <p className="text-muted-foreground">
            まだボードがありません。「新規ボード作成」から作成できます。
          </p>
        ) : (
          <ul className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {boards.map((board) => {
              const stats = boardStats(board.id);
              return (
                <li key={board.id}>
                  <Link href={`/boards/${board.id}`} className="block">
                    <Card className="h-full transition-colors hover:border-primary/50">
                      <CardHeader>
                        <CardTitle className="font-heading">{board.title}</CardTitle>
                        <div className="mt-1 flex gap-2">
                          <Badge variant="secondary">カード {stats.total}</Badge>
                          <Badge className="border-transparent bg-[var(--brand-success)]/15 text-[var(--brand-success)]">
                            完了 {stats.done}
                          </Badge>
                        </div>
                      </CardHeader>
                      <CardContent />
                      <CardFooter className="justify-between">
                        <div className="flex -space-x-2">
                          {stats.members.slice(0, 3).map((m) => (
                            <Avatar
                              key={m.id}
                              className="size-6 ring-2 ring-card"
                              aria-label={m.name}
                            >
                              <AvatarFallback className="text-[10px]">
                                {initials(m.name)}
                              </AvatarFallback>
                            </Avatar>
                          ))}
                          {stats.members.length > 3 && (
                            <span className="grid size-6 place-items-center rounded-full bg-muted text-[10px] text-muted-foreground ring-2 ring-card">
                              +{stats.members.length - 3}
                            </span>
                          )}
                        </div>
                        <span className="text-xs text-muted-foreground">
                          {stats.updatedLabel}
                        </span>
                      </CardFooter>
                    </Card>
                  </Link>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </AppShell>
  );
}

